<button class="btn btn-light mb-2 me-2" wire:click="viewOrder({{ $reserved->id }})">{{ $reserved->number }} · {{ number_format($reserved->quantity) }} {{ $products->firstWhere('stock_key',\Illuminate\Support\Facades\DB::table('batches')->where('id',$reservationBatch)->value('stock_key'))?->kind==='honey'?'g':'units' }} · {{ $reserved->ordered_on }}</button>
